#include "hex-image-reassembler.h"
#include "test_support.h"
#include <stdexcept>
static std::string rec(unsigned addr,unsigned type,std::vector<unsigned> d){static const char* h="0123456789ABCDEF";std::vector<unsigned>b={unsigned(d.size()),addr>>8,addr&255,type};b.insert(b.end(),d.begin(),d.end());unsigned sum=0;for(auto x:b)sum+=x;b.push_back((-sum)&255);std::string s=":";for(auto x:b){s+=h[(x>>4)&15];s+=h[x&15];}return s;}
int main(){using namespace hex_image;auto eof=rec(0,1,{});auto base=rec(0,4,{0x12,0x34});auto a=rec(0xfffe,0,{1,2});auto b=rec(0,0,{3,4});auto image=reassemble({base,a,b,eof});CHECK(image.spans==std::vector<Span>({{0x12340000,{3,4}},{0x1234fffe,{1,2}}}));auto same=reassemble({rec(2,0,{7,8}),rec(2,0,{7,8}),eof});CHECK(same.spans.size()==1);CHECK(reassemble({rec(0,0,{}),eof}).spans.empty());CHECK_THROWS(std::invalid_argument,reassemble({rec(2,0,{7}),rec(2,0,{8}),eof}));auto corrupt=rec(0,0,{1});corrupt.back()=corrupt.back()=='0'?'1':'0';CHECK_THROWS(std::invalid_argument,reassemble({corrupt,eof}));CHECK_THROWS(std::invalid_argument,reassemble({rec(0,0,{1})}));CHECK_THROWS(std::invalid_argument,reassemble({eof,eof}));CHECK_THROWS(std::invalid_argument,reassemble({rec(0,2,{0,0}),eof}));return charm_failures?1:0;}
